<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { api } from '../lib/api';
import { auth } from '../lib/auth';
import { groupLabel, hasPermission, manageableGroups } from '../lib/permissions';
import { dateTime, previewUrl, downloadUrl, type TeamApplication, type TeamSpace, type MailCampaign } from '../lib/platform';
const route=useRoute();
const items=ref<TeamApplication[]>([]),teams=ref<TeamSpace[]>([]),loading=ref(false),saving=ref(false),error=ref(''),notice=ref('');
const search=ref(''),direction=ref(''),team=ref(''),status=ref(String(route.query.status||'all')),selected=ref<string[]>([]);
const detail=ref<TeamApplication|null>(null),note=ref(''),decision=ref(''),room=ref(''),startAt=ref(''),interval=ref(10),startOrder=ref(1);
type Campaign=Omit<MailCampaign,'recipients'>&{recipients:(MailCampaign['recipients'][number]&{body?:string})[]};
const mail=ref<Campaign|null>(null),recipient=ref(0),confirmSend=ref(false),policyTeam=ref(''),exempt=ref<string[]>([]);
const statuses=[{value:'all',title:'全部报名'},{value:'pending',title:'待面试'},{value:'exempt',title:'线下面试已通过'},{value:'accepted',title:'已录取'},{value:'rejected',title:'未通过'}];
const admin=computed(()=>auth.user?.role==='admin'); const manager=computed(()=>hasPermission('recruitment'));
const groups=computed(()=>manageableGroups('recruitment')); const teamName=(id:string)=>teams.value.find(t=>t.id===id)?.name||'报名团队';
const stage=(i:TeamApplication)=>i.status==='accepted'?'accepted':i.status==='rejected'?'rejected':i.interview?.status==='exempt'?'exempt':'pending';
const label=(i:TeamApplication)=>statuses.find(s=>s.value===stage(i))?.title||'待面试';
const editable=(i:TeamApplication)=>hasPermission('recruitment',i.direction)&&stage(i)==='pending'&&(admin.value||i.userId!==auth.user?.id);
const scoped=computed(()=>items.value.filter(i=>(!direction.value||i.direction===direction.value)&&(!team.value||i.teamId===team.value)));
const filtered=computed(()=>scoped.value.filter(i=>(status.value==='all'||stage(i)===status.value)&&(i.userName+' '+(i.profile?.studentNumber||'')+' '+(i.profile?.major||'')).includes(search.value||'')).sort((a,b)=>(a.interview?.at||'9999').localeCompare(b.interview?.at||'9999')||(a.interview?.order||0)-(b.interview?.order||0)||a.createdAt.localeCompare(b.createdAt)));
const chosen=computed(()=>selected.value.map(id=>items.value.find(i=>i.id===id)).filter((i):i is TeamApplication=>!!i));
const canMail=computed(()=>chosen.value.length>0&&chosen.value.every(i=>hasPermission('mail',i.direction)&&i.interview?.at&&i.interview?.room));
const preview=computed(()=>mail.value?.recipients[recipient.value]);
const mailLabel=(s:string)=>({draft:'草稿',sending:'发送中',completed:'发送完成',partial:'部分失败',pending:'待发送',sent:'已发送',failed:'发送失败',unknown:'状态待核实'} as Record<string,string>)[s]||s;
async function load(){loading.value=true;error.value='';try{const [a,t]=await Promise.all([api.get<{items:TeamApplication[]}>('/interviews'),api.get<{items:TeamSpace[]}>('/teams')]);items.value=a.items||[];teams.value=t.items||[];selected.value=selected.value.filter(id=>items.value.some(i=>i.id===id&&editable(i)));if(detail.value)detail.value=items.value.find(i=>i.id===detail.value?.id)||null;else if(route.query.application){const target=items.value.find(i=>i.id===route.query.application);if(target)open(target);}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function perform(action:()=>Promise<void>){if(saving.value)return;saving.value=true;error.value='';try{await action()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(v=>v!==id):[...selected.value,id]}
function selectVisible(){const ids=filtered.value.filter(editable).map(i=>i.id);selected.value=ids.every(id=>selected.value.includes(id))?selected.value.filter(id=>!ids.includes(id)):[...new Set([...selected.value,...ids])]}
function move(n:number,d:number){const a=[...selected.value];if(n+d<0||n+d>=a.length)return;[a[n],a[n+d]]=[a[n+d]!,a[n]!];selected.value=a}
function open(i:TeamApplication){detail.value=i;note.value=i.interview?.note||'';decision.value='';setTimeout(()=>document.getElementById('interview-detail')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}
function planned(n:number){const t=Date.parse(startAt.value);return Number.isFinite(t)?dateTime(new Date(t+n*Number(interval.value)*60000).toISOString()):'未设置时间'}
function schedule(){if(!room.value.trim()||!Number.isFinite(Date.parse(startAt.value))||!Number.isInteger(Number(interval.value))||Number(interval.value)<1||!Number.isInteger(Number(startOrder.value))||Number(startOrder.value)<1){error.value='请填写教室、有效时间、正整数间隔和起始序号。';return}void perform(async()=>{await api.patch('/interviews/schedule',{applicationIds:selected.value,startAt:new Date(startAt.value).toISOString(),room:room.value.trim(),intervalMinutes:Number(interval.value),startOrder:Number(startOrder.value)});mail.value=null;await load();notice.value='面试安排已保存，尚未发送邮件。'})}
function decide(){if(!detail.value||!decision.value)return;const id=detail.value.id;void perform(async()=>{await api.post('/interviews/'+id+'/decision',{status:decision.value,note:note.value.trim()});notice.value=decision.value==='passed'?'已录取为本组新生，并进入阶段考核。':'已保存面试未通过结果。';decision.value='';await load()})}
function draftMail(){void perform(async()=>{mail.value=(await api.post<{item:Campaign}>('/interviews/notifications',{applicationIds:selected.value})).item;recipient.value=0;confirmSend.value=false;notice.value='已生成草稿，请逐人核对后发送。'})}
function refreshMail(){if(mail.value)void perform(async()=>{mail.value=(await api.get<{item:Campaign}>('/mail-campaigns/'+mail.value!.id)).item})}
function sendMail(){if(!mail.value||!confirmSend.value||mail.value.status!=='draft')return;void perform(async()=>{mail.value=(await api.post<{item:Campaign}>('/mail-campaigns/'+mail.value!.id+'/send')).item;confirmSend.value=false;notice.value='已提交发送，请刷新查看结果。'})}
function choosePolicy(){exempt.value=[...(teams.value.find(t=>t.id===policyTeam.value)?.interviewExemptDirections||[])]}
function savePolicy(){if(!policyTeam.value)return;void perform(async()=>{await api.patch('/teams/'+policyTeam.value,{interviewExemptDirections:exempt.value});await load();notice.value='后续报名规则已保存，既有报名记录不变。'})}
watch(() => route.query.status, value => { status.value = typeof value === "string" && statuses.some(s => s.value === value) ? value : "all"; });
watch(() => route.query.application, value => { const target=items.value.find(i=>i.id===value);if(target)open(target); });
onMounted(load);
</script>
<template>
<div class="page-content interview-page"><header class="heading"><div><h1 class="page-title">{{manager?'面试管理':'我的面试'}}</h1><p class="page-subtitle">报名进入面试，面试通过后录取为新生。</p></div><div class="d-flex ga-2"><v-btn v-if="manager" to="/recruitment-history" variant="text">历史候选人</v-btn><v-btn prepend-icon="mdi-refresh" variant="tonal" :loading="loading" :disabled="saving" @click="load">刷新</v-btn></div></header>
<v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</v-alert>
<div class="counts"><button v-for="s in statuses" :key="s.value" :class="{active:status===s.value}" @click="status=s.value"><strong>{{scoped.filter(i=>s.value==='all'||stage(i)===s.value).length}}</strong><span>{{s.title}}</span></button></div>
<div class="filters"><v-text-field v-model="search" variant="outlined" density="compact" label="姓名、学号或专业" prepend-inner-icon="mdi-magnify" clearable hide-details/><v-select v-model="direction" :items="[{title:'全部组别',value:''},...(manager?groups:items.map(i=>({title:groupLabel(i.direction),value:i.direction})))]" variant="outlined" density="compact" label="报名组别" hide-details/><v-select v-model="team" :items="[{title:'全部团队',value:''},...teams.map(t=>({title:t.name,value:t.id}))]" variant="outlined" density="compact" label="团队" hide-details/></div>
<v-progress-linear v-if="loading" indeterminate color="primary"/>
<v-card class="mb-6"><div class="section-head"><div><h2>报名与面试 <small>{{filtered.length}} 人</small></h2><p>{{manager?'选择待面试同学，批量设置时间、教室和顺序。':'面试安排和结果会在这里更新。'}}</p></div><v-btn v-if="manager" variant="text" :disabled="saving" @click="selectVisible">选择 / 取消筛选结果</v-btn></div><div class="table-wrap"><table><thead><tr><th v-if="manager">选择</th><th>候选人 / 组别</th><th>面试时间</th><th>教室 / 序号</th><th>进度</th><th>操作</th></tr></thead><tbody><tr v-for="i in filtered" :key="i.id"><td v-if="manager"><v-checkbox-btn v-if="editable(i)" :model-value="selected.includes(i.id)" :disabled="saving" :aria-label="'选择 '+i.userName" @update:model-value="toggle(i.id)"/><span v-else>—</span></td><td><button class="person-name" @click="open(i)">{{i.userName}}</button><small>{{groupLabel(i.direction)}} · {{i.profile?.studentNumber||'未填学号'}}</small></td><td>{{i.interview?.at?dateTime(i.interview.at):stage(i)==='pending'?'待安排':'无需安排'}}</td><td>{{i.interview?.room||'—'}}<small v-if="i.interview?.order">第 {{i.interview.order}} 位</small></td><td><v-chip :color="stage(i)==='accepted'?'success':stage(i)==='rejected'?'error':'primary'" size="small" variant="tonal">{{label(i)}}</v-chip></td><td><v-btn size="small" variant="text" color="primary" @click="open(i)">查看详情</v-btn></td></tr></tbody></table></div><div v-if="!filtered.length&&!loading" class="empty-state">当前筛选下没有报名记录</div></v-card>
<v-card v-if="chosen.length&&manager" class="pa-5 mb-6"><div class="section-head"><div><h2>批量面试安排 <small>{{chosen.length}} 人</small></h2><p>按下方顺序逐人安排时间，保存后再发送通知。</p></div><v-btn variant="text" :disabled="saving" @click="selected=[]">清空选择</v-btn></div><div class="schedule-fields"><v-text-field v-model="room" label="面试教室 / 地点 *" :disabled="saving"/><v-text-field v-model="startAt" type="datetime-local" label="首位面试时间 *" :disabled="saving"/><v-text-field v-model.number="interval" type="number" min="1" label="间隔（分钟）" :disabled="saving"/><v-text-field v-model.number="startOrder" type="number" min="1" label="起始序号" :disabled="saving"/></div><p class="text-caption text-medium-emphasis mb-3">按当前设备时区填写。筛选名单不会清空已选同学。</p><ol class="order-list"><li v-for="(i,n) in chosen" :key="i.id"><b>{{Number(startOrder)+n}}</b><span>{{i.userName}}<small>{{groupLabel(i.direction)}} · {{planned(n)}}</small></span><v-btn icon="mdi-arrow-up" size="small" variant="text" :aria-label="'上移 '+i.userName" :disabled="saving||n===0" @click="move(n,-1)"/><v-btn icon="mdi-arrow-down" size="small" variant="text" :aria-label="'下移 '+i.userName" :disabled="saving||n===chosen.length-1" @click="move(n,1)"/><v-btn icon="mdi-close" size="small" variant="text" :aria-label="'移除 '+i.userName" :disabled="saving" @click="toggle(i.id)"/></li></ol><div class="d-flex ga-3 flex-wrap mt-4"><v-btn color="primary" :loading="saving" @click="schedule">保存面试安排</v-btn><v-btn variant="tonal" :disabled="saving||!canMail" @click="draftMail">预览通知邮件</v-btn></div><p class="text-caption text-medium-emphasis mt-3">邮件使用已保存的安排。需先为所有选中同学设置时间和地点，并拥有对应组邮件权限。</p></v-card>
<v-card v-if="mail" class="pa-5 mb-6"><div class="section-head"><div><h2>面试通知预览</h2><p>{{mail.recipients.length}} 位收件人 · {{mailLabel(mail.status)}}</p></div><v-btn :loading="saving" variant="text" @click="refreshMail">刷新发送结果</v-btn></div><v-select v-model="recipient" label="逐人核对通知" :items="mail.recipients.map((r,n)=>({value:n,title:(r.name||r.userName||'')+' · '+r.email+' · '+mailLabel(r.status)}))"/><div v-if="preview" class="mail-preview"><strong>{{mail.subject}}</strong><p>{{preview.name||preview.userName}} &lt;{{preview.email}}&gt;</p><pre>{{preview.body||mail.body}}</pre><v-alert v-if="preview.error" type="error">{{preview.error}}</v-alert></div><template v-if="mail.status==='draft'"><v-checkbox v-model="confirmSend" :disabled="saving" label="已核对所有收件人、时间和教室，确认发送"/><v-btn color="primary" :disabled="!confirmSend" :loading="saving" @click="sendMail">确认发送 {{mail.recipients.length}} 封通知</v-btn></template><p v-else class="mt-3 text-caption">已发送 {{mail.recipients.filter(r=>r.status==='sent').length}} / {{mail.recipients.length}}；发送失败 {{mail.recipients.filter(r=>r.status==='failed').length}}。可在邮件管理查看完整记录。</p></v-card>
<v-card v-if="detail" id="interview-detail" class="pa-5 mb-6"><div class="section-head"><div><h2>{{detail.userName}} · 面试资料</h2><p>{{teamName(detail.teamId)}} · {{groupLabel(detail.direction)}}</p></div><v-btn icon="mdi-close" aria-label="收起面试资料" variant="text" :disabled="saving" @click="detail=null"/></div><div class="detail-grid"><section><div class="profile-heading"><img v-if="detail.profile?.photoFileId" :src="previewUrl(detail.profile.photoFileId)" alt="本人证件照"/><div><v-chip variant="tonal">{{label(detail)}}</v-chip><p class="text-caption">报名于 {{dateTime(detail.createdAt)}}</p></div></div><dl v-if="detail.profile"><div><dt>学校 / 专业</dt><dd>{{detail.profile.university}} / {{detail.profile.major}}</dd></div><div><dt>班级 / 学号</dt><dd>{{detail.profile.className}} / {{detail.profile.studentNumber}}</dd></div><div><dt>电话</dt><dd>{{detail.profile.phone}}</dd></div><div><dt>兴趣爱好</dt><dd>{{detail.profile.hobbies||'未填写'}}</dd></div></dl><p class="motivation">{{detail.motivation||'未填写报名说明'}}</p><div class="d-flex ga-2"><v-btn v-if="detail.resumeFileId" :href="previewUrl(detail.resumeFileId)" target="_blank" rel="noopener" variant="tonal">预览 PDF 简历</v-btn><v-btn v-if="detail.resumeFileId" :href="downloadUrl(detail.resumeFileId)" variant="text">下载</v-btn></div></section><section><h3>面试安排与结论</h3><p class="my-3">{{detail.interview?.at?dateTime(detail.interview.at):'尚未安排时间'}} · {{detail.interview?.room||'未设置教室'}}</p><v-alert v-if="detail.interview?.status==='exempt'" type="info" variant="tonal" class="mb-4">本轮已完成线下面试，无需再次安排。<v-btn v-if="detail.status==='pending'&&manager" :to="'/applications?application='+detail.id" variant="text">进入报名审核</v-btn></v-alert><v-alert v-if="detail.status==='accepted'" type="success" variant="tonal" class="mb-4">已录取，后续阶段通过与淘汰在新生考核中处理。</v-alert><v-textarea v-model="note" label="面试记录 / 评价" rows="4" maxlength="2000" :disabled="saving||!editable(detail)"/><template v-if="editable(detail)"><div v-if="!decision" class="d-flex ga-2"><v-btn color="primary" :disabled="saving" @click="decision='passed'">通过并录取</v-btn><v-btn color="error" variant="tonal" :disabled="saving" @click="decision='rejected'">面试未通过</v-btn></div><v-alert v-else type="warning" variant="tonal">确认将“{{detail.userName}}”记录为面试{{decision==='passed'?'通过并加入本组':'未通过'}}？<div class="d-flex ga-2 mt-3"><v-btn color="primary" :loading="saving" @click="decide">确认保存结论</v-btn><v-btn variant="text" :disabled="saving" @click="decision=''">取消</v-btn></div></v-alert></template></section></div></v-card>
<v-expansion-panels v-if="admin" class="mb-6"><v-expansion-panel title="本轮线下面试特例设置"><v-expansion-panel-text><p class="text-medium-emphasis mb-4">选择已在线下完成面试的组别。后续报名将标记为线下面试已通过；下一轮招新前清空选择即可恢复正常面试流程。既有记录保留。</p><v-select v-model="policyTeam" label="团队" :items="teams.map(t=>({title:t.name,value:t.id}))" @update:model-value="choosePolicy"/><v-select v-model="exempt" label="已完成线下面试的组别" :items="(teams.find(t=>t.id===policyTeam)?.directions||[]).map(d=>({title:groupLabel(d),value:d}))" multiple chips :disabled="!policyTeam||saving"/><v-btn color="primary" :disabled="!policyTeam" :loading="saving" @click="savePolicy">保存后续报名规则</v-btn></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
<v-snackbar :model-value="!!notice" @update:model-value="!$event&&(notice='')">{{notice}}</v-snackbar></div>
</template>
<style scoped>
.heading,.section-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.heading{margin-bottom:24px}.counts{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:24px}.counts button{padding:16px;background:white;border:1px solid #e3e8ee;border-radius:6px;text-align:left}.counts button.active{background:#eef6ff;border-color:rgb(var(--v-theme-primary))}.counts strong{display:block;font-size:26px;color:rgb(var(--v-theme-primary))}.counts span{font-size:12px;color:#77828c}.filters{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:16px;margin-bottom:24px}.section-head{padding:18px 0;margin-bottom:20px;border-bottom:1px solid #edf0f4}.v-card>.section-head:first-child{padding-left:20px;padding-right:20px}.section-head h2{font-size:18px;font-weight:500}.section-head small{font-size:13px;color:#87929d;margin-left:8px}.section-head p{font-size:13px;color:#7d8790;margin-top:6px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:760px}th{font-size:12px;color:#7e8993;background:#fafbfc;text-align:left;padding:12px 16px}td{font-size:13px;border-top:1px solid #edf0f4;padding:16px}td small{display:block;color:#87929d;margin-top:5px}.person-name{color:#25415c;font-size:15px;text-decoration:underline}.empty-state{text-align:center;padding:48px;color:#87929d}.schedule-fields{display:grid;grid-template-columns:1.3fr 1.4fr .8fr .8fr;gap:16px}.order-list{list-style:none;padding:0;border:1px solid #e4e9ef;border-radius:5px;max-height:420px;overflow:auto}.order-list li{display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:1px solid #edf0f4}.order-list span{flex:1}.order-list b{font-size:14px;color:rgb(var(--v-theme-primary))}.order-list small{display:block;color:#7f8a94;font-size:11px;margin-top:4px}.mail-preview{background:#f7f9fc;border:1px solid #e5eaf0;padding:18px}.mail-preview p{font-size:12px;margin:12px 0}.mail-preview pre{white-space:pre-wrap;font-family:inherit;line-height:1.8;overflow-wrap:anywhere}.detail-grid{display:grid;grid-template-columns:1fr 1.2fr;gap:32px}.profile-heading{display:flex;align-items:center;gap:16px}.profile-heading img{width:80px;height:108px;object-fit:contain;background:#f4f5f7}.profile-heading p{margin-top:12px}dl{display:grid;gap:14px;font-size:13px;margin:22px 0}dl>div{display:grid;grid-template-columns:86px 1fr;gap:10px}dt{color:#8a949c}dd{margin:0;overflow-wrap:anywhere}.motivation{white-space:pre-wrap;font-size:13px;margin:18px 0;line-height:1.8}h3{font-size:15px;font-weight:500}#interview-detail{scroll-margin-top:90px}button:focus-visible{outline:2px solid rgb(var(--v-theme-primary));outline-offset:2px}@media(max-width:1000px){.schedule-fields{grid-template-columns:1fr 1fr}}@media(max-width:700px){.heading,.section-head{flex-wrap:wrap}.counts{gap:5px}.counts button{padding:11px 5px}.counts span{font-size:11px}.filters,.schedule-fields,.detail-grid{grid-template-columns:1fr}.order-list li{gap:4px;padding:10px 6px}.order-list small{font-size:10px}}
.interview-page { width:100%; min-width:0; }.interview-page .filters { padding:20px 0 4px; align-items:center; }.interview-page .section-head { padding:20px 24px; margin:0; }.interview-page .table-wrap { margin-top:0; }.interview-page th, .interview-page td { padding-left:24px; padding-right:24px; }.interview-page .pa-5 .section-head { padding:0 0 16px; margin-bottom:20px; }</style>
